import{_ as o,o as a,c as r,ag as u}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"07 防骗与识局知识手册","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/handbook/07_防骗与识局知识.md","filePath":"topics/tianya/handbook/07_防骗与识局知识.md"}'),l={name:"topics/tianya/handbook/07_防骗与识局知识.md"};function q(i,t,d,n,e,s){return a(),r("div",null,[...t[0]||(t[0]=[u('<h1 id="_07-防骗与识局知识手册" tabindex="-1">07 防骗与识局知识手册 <a class="header-anchor" href="#_07-防骗与识局知识手册" aria-label="Permalink to &quot;07 防骗与识局知识手册&quot;">​</a></h1><blockquote><p>知识来源：天涯神贴 17（中国式骗局大全）、137（蜂麻燕雀）、156（加盟招商主管自白）、134（炒作热帖818）、81（内参记者）。每类骗术的操作流程均取自原帖正文，破绽点标注在每环之后。</p></blockquote><hr><h2 id="一、骗局通用结构-取信→收网的两阶段" tabindex="-1">一、骗局通用结构：取信→收网的两阶段 <a class="header-anchor" href="#一、骗局通用结构-取信→收网的两阶段" aria-label="Permalink to &quot;一、骗局通用结构：取信→收网的两阶段&quot;">​</a></h2><h3 id="_1-1-第一原理" tabindex="-1">1.1 第一原理 <a class="header-anchor" href="#_1-1-第一原理" aria-label="Permalink to &quot;1.1 第一原理&quot;">​</a></h3><p>17号帖（96岁老骗子自述）：&quot;世界上任何一种骗术，都首先需要取得对方的信任。&quot;同帖的效率对比：&quot;骗比偷来钱快得多&quot;——偷有被抓获的风险，骗是受害者&quot;乖乖把钱财送上来&quot;，事后甚至替骗子数钱。</p><h3 id="_1-2-取信阶段的手法清单-跨骗术通用" tabindex="-1">1.2 取信阶段的手法清单（跨骗术通用） <a class="header-anchor" href="#_1-2-取信阶段的手法清单-跨骗术通用" aria-label="Permalink to &quot;1.2 取信阶段的手法清单（跨骗术通用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>手法</th><th>原帖实例</th><th>识破点</th></tr></thead><tbody><tr><td>重复曝光建立熟悉感</td><td>金项圈局：中年人反复逗孩子玩熟后再消失（17）</td><td>主动凑近的&quot;熟人&quot;，都是陌生人</td></tr><tr><td>借身份背书</td><td>放鹞子团伙冒充女方全家上门（17）；招商公司挂&quot;国际集团&quot;头衔（156）</td><td>头衔可查证但查证者少；身份越完整越可疑</td></tr><tr><td>制造稀缺与竞争</td><td>十八玉罗汉局：你越想要，他越不卖（137）</td><td>真卖家怕你不买，假卖家怕你买快了</td></tr><tr><td>托儿围观造势</td><td>金点算命&quot;白送三卦&quot;引众人围堵（137）；展会意向名单挂满展台（156）</td><td>人群里的&quot;第一个受益者&quot;常常是雇的</td></tr><tr><td>让利试探</td><td>你一犹豫就送礼品、减加盟费、返装修费（156）</td><td>正规商家让利有底线，骗局让利没成本</td></tr><tr><td>小利铺路</td><td>假新娘先做&quot;好人媳妇&quot;再卷款（17）</td><td>得到的小便宜，是收网前的定金</td></tr></tbody></table><h3 id="_1-3-收网阶段的变体" tabindex="-1">1.3 收网阶段的变体 <a class="header-anchor" href="#_1-3-收网阶段的变体" aria-label="Permalink to &quot;1.3 收网阶段的变体&quot;">​</a></h3><ul><li><strong>一次性收割</strong>：婚骗（放鹞子）——彩礼到手即消失。</li><li><strong>分期收割</strong>：加盟术——加盟费→首批货款→后续&quot;培训费&quot;，每期都合法。</li><li><strong>合法化收割</strong>：156号帖的核心揭示——&quot;公司和顾客签的合同就是一个没有任何缝隙的网&quot;；收据代替发票、货款打入私人账户、专业律师团压阵，公安定性为&quot;合同纠纷&quot;而非诈骗。<strong>最高级的局不怕你告</strong>。</li><li><strong>暴力清场</strong>：讨说法者被&quot;售后&quot;（实为打手）拖出公司（156：&quot;像拖死狗一样拖出去&quot;）。</li></ul><h3 id="_1-4-贪念即杠杆-的机制" tabindex="-1">1.4 &quot;贪念即杠杆&quot;的机制 <a class="header-anchor" href="#_1-4-贪念即杠杆-的机制" aria-label="Permalink to &quot;1.4 &quot;贪念即杠杆&quot;的机制&quot;">​</a></h3><p>17号帖的判例——温纯征磨盘破沉尸案：&quot;关键不在足智多谋，在凶手贪那五十两银子。&quot;137号帖玉罗汉局的算账同理：程爷本可花140大洋/尊补齐，骗子让他&quot;偶遇&quot;零散罗汉被别人高价买走、最后一尊开价1000大洋不还价——<strong>局的核心不是骗走你的钱，是让你的贪心替他抬价</strong>。机制总结：</p><ol><li>先给你一个&quot;确定能赚/确定有缘&quot;的预期；</li><li>用小钱或小胜喂养预期（托儿买到便宜的、邻居娶到媳妇了）；</li><li>在预期最高点要求你加大投入；</li><li>此时旁人的任何提醒都会被你解释成&quot;嫉妒/不懂行&quot;（156号帖：展会受骗者&quot;哪怕亲朋好友如何规劝都很难回头&quot;，如《卖拐》中的范厨师）。 <strong>防贪原则：问&quot;这个好处为什么轮到我&quot;，答不上来就退出。</strong></li></ol><hr><h2 id="二、骗局分类图鉴-逐类操作流程" tabindex="-1">二、骗局分类图鉴：逐类操作流程 <a class="header-anchor" href="#二、骗局分类图鉴-逐类操作流程" aria-label="Permalink to &quot;二、骗局分类图鉴：逐类操作流程&quot;">​</a></h2><blockquote><p>江湖把营生分&quot;武&quot;&quot;文&quot;两路：偷、绑、害命是武行，有风险；骗是文行，无风险（17）。文行内部再分守规矩与不守规矩——137号帖的&quot;蜂麻燕雀缺&quot;五门，蜂麻燕三门严禁伤人，&quot;要给自己留阴德&quot;，缺门不择手段。看懂分类，就懂得不同骗局要防什么。</p></blockquote><h3 id="_2-1-街头术-金点相面-137号帖-金点-节" tabindex="-1">2.1 街头术：金点相面（137号帖&quot;金点&quot;节） <a class="header-anchor" href="#_2-1-街头术-金点相面-137号帖-金点-节" aria-label="Permalink to &quot;2.1 街头术：金点相面（137号帖&quot;金点&quot;节）&quot;">​</a></h3><p>流程五环：</p><ol><li><strong>聚人</strong>：倒着写字、边唱边画，&quot;画龙龙成云，画虎虎成风&quot;——用新鲜感截住人流。</li><li><strong>包罗断语</strong>：对着人群一口气说&quot;有人犯小人要打官司、有人家中有人偷汉、有人找营生、有人鸿运当头、有人家有病人、有人犯口舌&quot;——总有一款命中任何人。</li><li><strong>锁足</strong>：&quot;唯独一人不能说，就是那个……&quot;（做王八手势）——谁走谁就默认是自己，全场没人敢走。</li><li><strong>筛选</strong>：白送三卦，但&quot;聋子哑巴不送、傻子不送&quot;——过滤掉听不懂暗示的人，留下能被话术操控的。</li><li><strong>逐个收钱</strong>：先免费制造&quot;灵验&quot;，再一人一人深聊收钱。 破绽：断语全是概率题；锁足逻辑是绑架；&quot;免费&quot;是筛选器。<strong>对策：人群中永远可以转身就走——他没有任何办法。</strong></li></ol><h3 id="_2-2-局术-蜂门十八玉罗汉-137号帖" tabindex="-1">2.2 局术：蜂门十八玉罗汉（137号帖） <a class="header-anchor" href="#_2-2-局术-蜂门十八玉罗汉-137号帖" aria-label="Permalink to &quot;2.2 局术：蜂门十八玉罗汉（137号帖）&quot;">​</a></h3><p>流程：</p><ol><li>摸底：程爷已集齐十七尊玉罗汉，痴迷凑整。</li><li>布点：各古玩店&quot;恰好&quot;陆续出现散尊，被不同&quot;买家&quot;买走，市价被抬高。</li><li>引局：外地商人携最后一尊现身，自称祖传，为&quot;祖上托梦祈福&quot;而来，一口回绝出售。</li><li>抬价：第二次登门开价1000大洋（市价140），商人&quot;勉为其难&quot;答应。</li><li>收网：凑齐十八尊风光大办，总花费2900多，比真实市价多花约400大洋——&quot;让所有人都满意，回头还得连连道谢&quot;。 破绽（王定一的识局示范）：①气质装不出来——假商人&quot;穿得富贵却不似久居富贵之人&quot;，牙齿不齐（水质卫生习惯暴露出身）；②自称&quot;祖传&quot;与其气质矛盾；③&quot;故意展现给你的江湖气，就是让你入局的棋子&quot;。<strong>对策：对&quot;来得太巧&quot;的卖家，查其来历连续追问三层。</strong></li></ol><h3 id="_2-3-装神弄鬼术-麻-马门" tabindex="-1">2.3 装神弄鬼术（麻/马门） <a class="header-anchor" href="#_2-3-装神弄鬼术-麻-马门" aria-label="Permalink to &quot;2.3 装神弄鬼术（麻/马门）&quot;">​</a></h3><ul><li>正用（17号帖三师叔装神仙）：生石灰遇雪生烟、加热酒壶、春分赤云主兵荒——全部是化学与天文常识。</li><li>反用（137号帖惩治骗婚团伙）：白衣假鬼、坟头埋伏、&quot;吊死鬼&quot;木头假人——骗子最信鬼神，也最怕鬼神。 破绽：所有&quot;神迹&quot;必有一个物理机关。<strong>对策：任何超自然解释出现时，先找机关；找不到，要求复现一次。</strong></li></ul><h3 id="_2-4-美色婚骗术-放鹞子-17号帖完整流程-137号帖韩家局同型" tabindex="-1">2.4 美色婚骗术：放鹞子（17号帖完整流程，137号帖韩家局同型） <a class="header-anchor" href="#_2-4-美色婚骗术-放鹞子-17号帖完整流程-137号帖韩家局同型" aria-label="Permalink to &quot;2.4 美色婚骗术：放鹞子（17号帖完整流程，137号帖韩家局同型）&quot;">​</a></h3><ol><li><strong>组队</strong>：假新娘（&quot;鹞子&quot;）+假父母+探路人，团伙分钱。</li><li><strong>选猎物</strong>：深入偏远山区，专挑娶不上妻的老光棍（信息闭塞、防骗能力弱、急于成家）。</li><li><strong>控距</strong>：声称女方家&quot;只有几十里&quot;——女方一家必须能迅速上门，太远会让光棍起疑&quot;没法打听底细&quot;。</li><li><strong>上门</strong>：全家配合演出，尽快收彩礼办婚事。</li><li><strong>验证伪装</strong>：新婚夜用鸽子血装猪尿泡伪装处子，第二天男方&quot;把褥子晾在院墙上&quot;让全村看。</li><li><strong>消失</strong>：卷款逃走，男方人财两空。 原帖定性：凌光祖鄙视此术&quot;没有技术含量，临时雇一个娼妓也能干&quot;——<strong>骗术的鄙视链本身告诉我们：越低级的局越依赖信息封锁</strong>。破绽：女方家&quot;恰好&quot;就在附近、婚事推进快得反常、女方家人际关系在本地无一可查。137号帖的反制示范：识破后不声张，用装神弄鬼反吓骗子，追回损失。 <strong>对策：远距离婚恋，实地探访女方家庭、邻里，见其亲友与旧识，任何&quot;家太远没法去&quot;的借口都按骗局处理。</strong></li></ol><h3 id="_2-5-古玩做旧术-17号帖-做旧业" tabindex="-1">2.5 古玩做旧术（17号帖&quot;做旧业&quot;） <a class="header-anchor" href="#_2-5-古玩做旧术-17号帖-做旧业" aria-label="Permalink to &quot;2.5 古玩做旧术（17号帖&quot;做旧业&quot;）&quot;">​</a></h3><p>三套来源话术：冒充传家宝、冒充盗墓出土、冒充败家卖家急售。配套手段：字画作旧、伙同&quot;行家&quot;掌眼抬价、先卖真小件建立信任再卖假大件。原帖定性：做旧业靠阴险、互相拆台，江相派靠智谋讲规矩——<strong>同是骗局，&quot;有无行业底线&quot;决定它坑人的深度</strong>。破绽：来源故事无法交叉验证；价格远低于行情的&quot;急售&quot;。<strong>对策：古玩只买&quot;来源可追溯+价格可解释&quot;的物件。</strong></p><h3 id="_2-6-加盟招商术-156号帖完整话术链" tabindex="-1">2.6 加盟招商术（156号帖完整话术链） <a class="header-anchor" href="#_2-6-加盟招商术-156号帖完整话术链" aria-label="Permalink to &quot;2.6 加盟招商术（156号帖完整话术链）&quot;">​</a></h3><p>环节流程与破绽点：</p><table tabindex="0"><thead><tr><th>环节</th><th>公司动作</th><th>破绽点</th></tr></thead><tbody><tr><td>1.买客资</td><td>招商网站购买意向者联系方式</td><td>正规品牌不缺客源，很少广撒网&quot;邀请考察&quot;</td></tr><tr><td>2.话务筛选</td><td>分&quot;有效顾客（已租店面的）&quot;&quot;可发展型&quot;&quot;扯淡型&quot;；对有效顾客&quot;穷追猛打，不到翻脸不罢休&quot;</td><td>反常热情；你越犹豫他越积极</td></tr><tr><td>3.邀约进京</td><td>抓心理：诱人利润、短期赚大钱、&quot;全程指导&quot;</td><td>&quot;指导&quot;最后只是一张光盘</td></tr><tr><td>4.洗脑面谈</td><td>主管面谈：夸大名头、夸大利润</td><td>名头可查工商；利润算法不给你成本表</td></tr><tr><td>5.样板间</td><td>名牌买来撕标，换贴自家商标</td><td>要求看生产车间/仓库即被拒（&quot;在浙江，不对外开放&quot;）</td></tr><tr><td>6.看店</td><td>只带看&quot;还没倒闭、打过招呼&quot;的两家</td><td>店数不足、店主言辞一致得可疑</td></tr><tr><td>7.签约收款</td><td>加盟费3万+首批货款3万；收款走私人账户、只给收据不给发票</td><td>发票是硬指标；公司账户收款是天条</td></tr><tr><td>8.发货</td><td>发批发市场积压货，贴标后涨三倍，拿货价高于市场零售</td><td>收到货先比价，&quot;拿货价&gt;零售价&quot;即骗局实锤</td></tr><tr><td>9.售后</td><td>&quot;公司的货就这样，原要不要；想退货？门都没有；不服去告我们&quot;</td><td>正规品牌有退换货与督导制度</td></tr><tr><td>10.法律消化</td><td>合同无懈可击+律师团；公安定性合同纠纷；工商只管虚假宣传；上门闹事者由&quot;售后&quot;打手处理</td><td>靠&quot;你耗不起&quot;盈利的生意必然是骗局</td></tr></tbody></table><p>配套事实（同帖）：北京此类公司约2万家，某中型公司三年近600家加盟商、老板净落约两千万；明星代言、正规展会、权威网站认证均可花钱买到。<strong>受害者画像</strong>：务工返乡者、下岗创业者——&quot;真正有钱有势的人不会看上这种小生意&quot;，所以加盟费定在1.2万–6万之间：够得着、又不至于让你请律师。</p><h3 id="_2-7-网络募捐与钓鱼术-134号帖" tabindex="-1">2.7 网络募捐与钓鱼术（134号帖） <a class="header-anchor" href="#_2-7-网络募捐与钓鱼术-134号帖" aria-label="Permalink to &quot;2.7 网络募捐与钓鱼术（134号帖）&quot;">​</a></h3><ul><li><strong>卖身救母型</strong>：真实悲惨故事+照片+煽情文字→募款→被曝生活细节不符→对骂反转。破绽：细节（穿着、手机、消费）与叙事冲突；募款账户为个人。</li><li><strong>煤老板招女婿型</strong>：车房照片俱全的钓鱼帖，吸引应征者按格式自曝年龄学历收入联系方式。破绽：受益方是&quot;信息收集&quot;本身。<strong>对策：网上填资料前问一句——对方收集这个干什么。</strong></li><li><strong>姜岩事件型</strong>：真实悲剧→求助→声讨→人肉→隐私灾难。教训：情绪最激动时发布的&quot;正义&quot;，往往由 anonymous 的人肉执行，误伤与被利用概率极高。</li></ul><h3 id="_2-8-权威包装术-81号帖" tabindex="-1">2.8 权威包装术（81号帖） <a class="header-anchor" href="#_2-8-权威包装术-81号帖" aria-label="Permalink to &quot;2.8 权威包装术（81号帖）&quot;">​</a></h3><p>结构三件套：<strong>真实框架</strong>（老山战役、刘民壮《中国神农架》、保密制度科普——皆可查证）+<strong>不可验证内核</strong>（活体生物兵器、野人尸体&quot;超过两位数&quot;）+<strong>拒绝解释的免责声明</strong>（&quot;信不信由你，我只负责写不负责解释&quot;；人名全化名）。破绽：核心断言永远没有可独立核对的信源；用&quot;脱密&quot;“纪律”预先解释为何拿不出证据。<strong>对策：把&quot;可查证部分&quot;与&quot;结论部分&quot;切开——前者为真不代表后者为真。</strong></p><hr><h2 id="三、加盟招商防骗四铁律-156号帖原文归纳" tabindex="-1">三、加盟招商防骗四铁律（156号帖原文归纳） <a class="header-anchor" href="#三、加盟招商防骗四铁律-156号帖原文归纳" aria-label="Permalink to &quot;三、加盟招商防骗四铁律（156号帖原文归纳）&quot;">​</a></h2><ol><li><strong>搜索铁律</strong>：项目名+&quot;骗子&quot;在搜索引擎查一遍。投诉多=骗局；这是成本最低的第一道闸（注意：新公司可能尚无投诉，需配合后三条）。</li><li><strong>实体店铁律</strong>：要加盟的品牌在总部所在城市没有两家以上直营实体店，即是骗局，&quot;无论它如何解释你都不要相信&quot;。</li><li><strong>让利警报</strong>：你一犹豫就送礼品、减加盟费、返现金、返装修费——正规品牌不与加盟商谈这些。</li><li><strong>实物铁律</strong>：无论厂址说得多远，花几百块路费也要亲眼看生产车间和仓库。作者的原话算账：&quot;是被骗去几万好，还是花几百块路费看一下好？&quot;</li></ol><p>补充判断（156号帖末尾）：正规品牌门槛高、名额早招满、费用远超几万元；&quot;轻松挣大钱的鬼话&quot;若为真，没人会漫天找加盟商。</p><hr><h2 id="四、媒介素养-识别被制造的热点与-真实感" tabindex="-1">四、媒介素养：识别被制造的热点与&quot;真实感&quot; <a class="header-anchor" href="#四、媒介素养-识别被制造的热点与-真实感" aria-label="Permalink to &quot;四、媒介素养：识别被制造的热点与&quot;真实感&quot;&quot;">​</a></h2><h3 id="_4-1-炒作五征兆-134号帖案例归纳" tabindex="-1">4.1 炒作五征兆（134号帖案例归纳） <a class="header-anchor" href="#_4-1-炒作五征兆-134号帖案例归纳" aria-label="Permalink to &quot;4.1 炒作五征兆（134号帖案例归纳）&quot;">​</a></h3><ol><li><strong>剧情过于完整</strong>：起承转合俱全，情绪节点精准（卖身救母帖的围巾细节）。</li><li><strong>关键处必有自证材料</strong>：照片、证件、&quot;内部爆料&quot;恰好在争议时出现。</li><li><strong>当事人只在线上现身</strong>：无法线下核实，ID行为模式异常（文笔统一、回复迅速）。</li><li><strong>事成后消失</strong>：募款完成/话题引爆后当事人不再回应。</li><li><strong>存在模糊受益方</strong>：流量主、募款人、八卦产业链、竞品——顺着&quot;谁受益&quot;查，比顺着&quot;谁可怜&quot;查有效。</li></ol><h3 id="_4-2-真实感-话术的识别流程-134-81" tabindex="-1">4.2 &quot;真实感&quot;话术的识别流程（134+81） <a class="header-anchor" href="#_4-2-真实感-话术的识别流程-134-81" aria-label="Permalink to &quot;4.2 &quot;真实感&quot;话术的识别流程（134+81）&quot;">​</a></h3><ol><li>拆分可查证部分与结论部分（81号帖：战史细节真，&quot;生物兵器&quot;假）。</li><li>检查证据链是否闭合：核心断言有没有独立信源？没有——降级为&quot;故事&quot;。</li><li>检查当事人对质疑的反应：拒绝一切解释（&quot;只负责写不负责解释&quot;）=不承担为真的义务。</li><li>检查传播路径：是自然发酵还是名单式搬运（134号帖：意向名单&quot;做托的、受骗的混杂其中&quot;）。</li><li>终极检验：把&quot;如果这是假的&quot;代入，看叙事是否同样成立——成立，则按假处理。</li></ol><hr><h2 id="五、防骗检查清单-可打印版" tabindex="-1">五、防骗检查清单（可打印版） <a class="header-anchor" href="#五、防骗检查清单-可打印版" aria-label="Permalink to &quot;五、防骗检查清单（可打印版）&quot;">​</a></h2><h3 id="a-签合同前" tabindex="-1">A. 签合同前 <a class="header-anchor" href="#a-签合同前" aria-label="Permalink to &quot;A. 签合同前&quot;">​</a></h3><ul><li>[ ] 对方全称在工商系统是否可查？法人、股东、注册时间、注册资本各是什么？</li><li>[ ] 法人是否为与业务无关的老人？（156号帖：法人是挂名退休老头）</li><li>[ ] 收款账户是公司账户还是私人账户？能否开具发票？</li><li>[ ] 合同中退费条款、违约条款、管辖条款是否读完全文？能否拿走一份盖章原件？</li><li>[ ] 有无专业律师可咨询一小时的合同审查？（成本几百元，对应骗局客单价数万元）</li></ul><h3 id="b-给钱前" tabindex="-1">B. 给钱前 <a class="header-anchor" href="#b-给钱前" aria-label="Permalink to &quot;B. 给钱前&quot;">​</a></h3><ul><li>[ ] &quot;项目名+骗子&quot;搜索结果如何？</li><li>[ ] 承诺的利润有没有成本表支撑？拿货价是否低于市场零售价？</li><li>[ ] 我看过生产车间/仓库/实体店吗？是自己随机去的还是对方安排的？</li><li>[ ] 对方为何突然让利？（小礼品/减免/返现＝警报）</li><li>[ ] 这个好处为什么轮到我？</li><li>[ ] 家人朋友反对的理由，我逐条反驳了吗？还是只是情绪性否认？</li></ul><h3 id="c-加入前-长期关系-加盟-投资-婚恋-合伙" tabindex="-1">C. 加入前（长期关系：加盟/投资/婚恋/合伙） <a class="header-anchor" href="#c-加入前-长期关系-加盟-投资-婚恋-合伙" aria-label="Permalink to &quot;C. 加入前（长期关系：加盟/投资/婚恋/合伙）&quot;">​</a></h3><ul><li>[ ] 对方身份三层追问：来历、旧识、消费习惯是否自洽？（玉罗汉局的牙齿原理）</li><li>[ ] 见过对方的家人/总部/旧客户吗？能交叉验证吗？</li><li>[ ] 婚恋对象：实地探访过其家庭与邻里吗？&quot;家太远&quot;是不是固定借口？</li><li>[ ] 投资项目：收益超过常识（&gt;15%/年）的部分，风险由谁承担？</li><li>[ ] 我现在的判断，是因为证据，还是因为已经投入了很多/已经相信很久了？（沉没成本＝收网信号）</li><li>[ ] 最坏情况发生，我损失多少钱、能否承受？</li></ul><p><strong>三条使用规则</strong>：清单是拦&quot;当场冲动&quot;的，不是拦深思熟虑的；任何一项答不上来就停；对方催得越急，清单走得越慢。</p>',55)])])}const c=o(l,[["render",q]]);export{g as __pageData,c as default};
